/**
 * Phase 88: additive, fail-closed adapter CONTRACT for an authorized HTML source.
 *
 * This file DOES NOT import unavailable v4.14 Phase68/69/72 signatures. Wiring
 * them is mandatory before production; injecting a fake 'approved' reader is
 * not authorization. No network, web search, ranking or LLM logic exists here.
 */
import { phase87Call } from '../phase87/phase87_client.ts';

export type ReadRequest = Readonly<{
  url: string;
  model: string;
  category: string;
  operation: 'manufacturer_specifications';
  asOf: string;
}>;

/** Must be generated by the REAL Phase69 authorization + source read. */
export type Phase69ApprovedHTML = Readonly<{
  state: 'approved_source_read';
  requestedUrl: string;
  finalUrl: string;
  body: string;
  contentType: string;
  sourcePolicyId: string;
  acquisitionPlanId: string;
  rightsReviewId: string;
  robots: 'allowed';
  websiteTerms: 'allowed';
  extractionRights: 'allowed';
  operation: 'manufacturer_specifications';
}>;

export type QuarantineClaim = Readonly<{
  category: string;
  model: string;
  sourceUrl: string;
  fieldKey: string;
  value: number;
  unit: string;
  origin: 'manufacturer_declared';
  evidenceState: 'quarantined_not_independently_tested';
  strategySha256: string;
  sourcePolicyId: string;
  acquisitionPlanId: string;
  rightsReviewId: string;
  registryReviewId: string;
  sourceReadAt: string;
}>;

export type Phase72QuarantineReceipt = Readonly<{
  state: 'quarantined';
  acceptedCount: number;
  receiptId: string;
  /** This is not a publication/score/ranking permission. */
  evidenceRole: 'manufacturer_declared';
}>;

export type ReviewedRegistryReceipt = Readonly<{
  state: 'reviewed_field_registry';
  category: string;
  registryReviewId: string;
  fieldKeys: readonly string[];
}>;

export type IntakeDependencies = Readonly<{
  /** Must resolve to the existing Phase85/category's independently reviewed registry. */
  resolveReviewedFieldRegistry: (category: string, asOf: string) => Promise<ReviewedRegistryReceipt>;
  /** Connect directly to existing Phase68/69 planner + readApprovedSource. */
  readApprovedSource: (request: ReadRequest) => Promise<Phase69ApprovedHTML>;
  /** Connect to existing Phase72 quarantined evidence intake, not ranking. */
  quarantineManufacturerClaims: (
    claims: readonly QuarantineClaim[],
  ) => Promise<Phase72QuarantineReceipt>;
  /** Optional test seam. Production uses phase87Call with its CLI. */
  extractStoredRecipe?: typeof phase87Call;
}>;

export type IntakeInput = Readonly<{
  url: string;
  model: string;
  category: string;
  asOf: string;
  dbPath: string;
  recipeId: string;
  /** Must come from reviewed mainline category registry, not from the model. */
  allowedFieldKeys: readonly string[];
}>;

export type IntakeResult = Readonly<{
  state: 'quarantined';
  sourceUrl: string;
  recipeId: string;
  acceptedCount: number;
  receiptId: string;
  /** Not evidence of independent testing or fitness for ranking. */
  rankingApproved: false;
  publicationApproved: false;
  modelCalls: 0;
}>;

const HASH = /^[a-f0-9]{64}$/;
const FIELD = /^[a-z][a-z0-9_]{1,63}$/;
// Phase87 may extract manufacturer specifications only. No retailer data,
// recommendation scores or inferred manufacturing retirement in this lane.
const EXCLUDED_FIELD = /(?:^|_)(?:price|prices|discount|stock|inventory|availability|affiliate|merchant|seller|rating|ratings|review|reviews|recommendation|ranking|score|discontinued|retired|retirement)(?:_|$)/;
function deny(reason: string): never { throw new Error(`phase88_${reason}`); }
function validReceipt(s: unknown): s is string {
  return typeof s === 'string' && s.trim().length >= 6 && s.length <= 256;
}
function matchSourceURL(requested: string, actual: string): boolean {
  try {
    const a = new URL(requested), b = new URL(actual);
    if (a.protocol !== 'https:' || b.protocol !== 'https:' ||
        a.username || b.username || a.password || b.password ||
        a.port || b.port || a.hash || b.hash) return false;
    // Different query, path, host, case or even innocuous redirect requires
    // separate Phase69 authorization, so fail closed at this interface.
    return a.href === b.href;
  } catch { return false; }
}
function verifySource(read: Phase69ApprovedHTML, input: IntakeInput): void {
  if (!read || read.state !== 'approved_source_read' ||
      read.operation !== 'manufacturer_specifications' ||
      read.robots !== 'allowed' || read.websiteTerms !== 'allowed' ||
      read.extractionRights !== 'allowed') deny('unapproved_source');
  if (!matchSourceURL(input.url, read.requestedUrl) ||
      !matchSourceURL(input.url, read.finalUrl)) deny('source_redirect_or_mismatch');
  if (!/^text\/html(?:\s*;|$)/i.test(read.contentType)) deny('wrong_content_type');
  if (!validReceipt(read.sourcePolicyId) ||
      !validReceipt(read.acquisitionPlanId) ||
      !validReceipt(read.rightsReviewId)) deny('source_receipts_missing');
  if (typeof read.body !== 'string' || Buffer.byteLength(read.body, 'utf8') > 750_000)
    deny('html_too_large');
}

type Phase87Extracted = Record<string, {
  value: number; unit: string; origin: string; evidence_state: string;
  model: string; source_url: string; strategy_sha256: string;
}>;

/**
 * The only execution path: source rights -> reviewed recipe -> Phase72 quarantine.
 * No automatic LLM fallback. No partial inserts after validation failure.
 */
export async function intakeApprovedHTML(
  input: IntakeInput, dependencies: IntakeDependencies,
): Promise<IntakeResult> {
  if (!input || !matchSourceURL(input.url, input.url)) deny('invalid_https_url');
  if (!input.model || input.model.length > 100 || !input.model.trim()) deny('invalid_model');
  if (!/^[a-z][a-z0-9_-]{1,50}$/.test(input.category)) deny('invalid_category');
  if (!HASH.test(input.recipeId)) deny('invalid_reviewed_recipe_id');
  if (!input.dbPath || typeof input.dbPath !== 'string') deny('invalid_store_path');
  if (!/^[0-9]{4}-[0-9]{2}-[0-9]{2}T/.test(input.asOf) || Number.isNaN(Date.parse(input.asOf)))
    deny('invalid_as_of');
  if (!Array.isArray(input.allowedFieldKeys) || !input.allowedFieldKeys.length ||
      input.allowedFieldKeys.length > 32 ||
      input.allowedFieldKeys.some(k => !FIELD.test(k) || EXCLUDED_FIELD.test(k)) ||
      new Set(input.allowedFieldKeys).size !== input.allowedFieldKeys.length)
    deny('invalid_reviewed_field_registry');
  if (typeof dependencies?.resolveReviewedFieldRegistry !== 'function' ||
      typeof dependencies?.readApprovedSource !== 'function' ||
      typeof dependencies?.quarantineManufacturerClaims !== 'function')
    deny('missing_authorized_mainline_dependencies');

  // Verify selected fields against independently reviewed, mainline registry first.
  const registry = await dependencies.resolveReviewedFieldRegistry(input.category,input.asOf);
  if (!registry || registry.state !== 'reviewed_field_registry' ||
      registry.category !== input.category || !validReceipt(registry.registryReviewId) ||
      !Array.isArray(registry.fieldKeys) ||
      new Set(registry.fieldKeys).size !== registry.fieldKeys.length ||
      input.allowedFieldKeys.some(key => !registry.fieldKeys.includes(key)))
    deny('unreviewed_category_fields');

  // Calls existing Phase69 boundary; this adapter NEVER fetches directly.
  const approved = await dependencies.readApprovedSource(Object.freeze({
    url: input.url, model: input.model, category: input.category,
    operation: 'manufacturer_specifications', asOf: input.asOf,
  }));
  verifySource(approved, input);

  const bridge = dependencies.extractStoredRecipe ?? phase87Call;
  const extracted = await bridge<Phase87Extracted>('extract_stored', {
    db_path: input.dbPath, recipe_id: input.recipeId, url: input.url,
    model: input.model, html: approved.body,
  });
  if (!extracted || typeof extracted !== 'object' || Array.isArray(extracted))
    deny('invalid_extraction');
  const keys = Object.keys(extracted);
  if (!keys.length || keys.length > input.allowedFieldKeys.length ||
      keys.some(k => !input.allowedFieldKeys.includes(k)))
    deny('unreviewed_extracted_field');
  const claims: QuarantineClaim[] = keys.sort().map(fieldKey => {
    const claim = extracted[fieldKey];
    if (!claim || claim.origin !== 'manufacturer_declared' ||
        claim.evidence_state !== 'quarantined_not_independently_tested' ||
        claim.source_url !== input.url || claim.model !== input.model ||
        claim.strategy_sha256 !== input.recipeId ||
        typeof claim.value !== 'number' || !Number.isFinite(claim.value) ||
        typeof claim.unit !== 'string' || !/^[a-zA-Z°%]{1,5}$/.test(claim.unit))
      deny('invalid_or_promoted_manufacturer_claim');
    return Object.freeze({
      category: input.category, model: input.model, sourceUrl: input.url,
      fieldKey, value: claim.value, unit: claim.unit,
      origin: 'manufacturer_declared',
      evidenceState: 'quarantined_not_independently_tested',
      strategySha256: input.recipeId,
      sourcePolicyId: approved.sourcePolicyId,
      acquisitionPlanId: approved.acquisitionPlanId,
      rightsReviewId: approved.rightsReviewId,
      registryReviewId: registry.registryReviewId,
      sourceReadAt: input.asOf,
    });
  });
  const receipt = await dependencies.quarantineManufacturerClaims(Object.freeze(claims));
  if (!receipt || receipt.state !== 'quarantined' ||
      receipt.acceptedCount !== claims.length ||
      receipt.evidenceRole !== 'manufacturer_declared' ||
      !validReceipt(receipt.receiptId)) deny('quarantine_receipt_invalid');
  return Object.freeze({
    state: 'quarantined', sourceUrl: input.url, recipeId: input.recipeId,
    acceptedCount: claims.length, receiptId: receipt.receiptId,
    rankingApproved: false, publicationApproved: false, modelCalls: 0,
  });
}
